package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen3Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_DoubleDashProtection() {
        assertNull(NumberUtils.createNumber("--123"));
    }

    @Test
    public void testCreateNumber_Hexadecimal() {
        // Tests the str.startsWith("0x") || str.startsWith("-0x") branch
        assertEquals(Integer.valueOf(16), NumberUtils.createNumber("0x10"));
        assertEquals(Integer.valueOf(-16), NumberUtils.createNumber("-0x10"));
    }

    @Test
    public void testCreateNumber_IntegerTypes() {
        // Tests the dec == null && exp == null branch for Integer/Long/BigInteger
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123"));
        // Large number to trigger BigInteger
        BigInteger big = new BigInteger("123456789012345678901234567890");
        assertEquals(big, NumberUtils.createNumber("123456789012345678901234567890"));
    }

    @Test
    public void testCreateNumber_DecimalAndExponentTypes() {
        // Tests the dec != null or exp != null branch
        assertEquals(Float.valueOf(123.45f), NumberUtils.createNumber("123.45"));
        assertEquals(Double.valueOf(123.45D), NumberUtils.createNumber("123.45"));
        assertEquals(new BigDecimal("123.45"), NumberUtils.createNumber("123.45"));

        assertEquals(Float.valueOf(1.2e2f), NumberUtils.createNumber("1.2e2"));
        assertEquals(Double.valueOf(1.2e2D), NumberUtils.createNumber("1.2E2"));
        assertEquals(new BigDecimal("1.2e2"), NumberUtils.createNumber("1.2e2"));
    }

    @Test
    public void testCreateNumber_ExplicitSuffixes() {
        // Test 'L' / 'l' suffix
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(-123L), NumberUtils.createNumber("-123l"));
        // Large L to trigger BigInteger
        BigInteger bigL = new BigInteger("123456789012345678901234567890");
        assertEquals(bigL, NumberUtils.createNumber("123456789012345678901234567890L"));

        // Test 'F' / 'f' suffix
        assertEquals(Float.valueOf(123.45f), NumberUtils.createNumber("123.45F"));
        assertEquals(Float.valueOf(123.45f), NumberUtils.createNumber("123.45f"));

        // Test 'D' / 'd' suffix
        assertEquals(Double.valueOf(123.45D), NumberUtils.createNumber("123.45D"));
        assertEquals(Double.valueOf(123.45D), NumberUtils.createNumber("123.45d"));
    }

    @Test
    public void testCreateNumber_InvalidSuffixes() {
        // Test invalid suffix or logic branch
        try {
            NumberUtils.createNumber("123.45L"); // L with decimal is invalid in this logic
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // expected
        }

        try {
            NumberUtils.createNumber("123.45X"); // Invalid char
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // expected
        }
    }

    @Test
    public void testCreateNumber_ExponentEdgeCases() {
        // Test expPos < decPos logic: "1e.5" is invalid
        try {
            NumberUtils.createNumber("1e.5");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // expected
        }

        // Test exponent with suffix: "123e2f"
        assertEquals(Float.valueOf(12300.0f), NumberUtils.createNumber("123e2f"));
    }

    @Test
    public void testCreateNumber_PrecisionAndZeroLogic() {
        // Test the allZeros logic for Float/Double precision check
        // If it's all zeros but input wasn't all zeros, it falls through to BigDecimal
        // This is a complex branch in the code provided
        assertEquals(new BigDecimal("0.0000000000000000000000000000000000000001"), 
                     NumberUtils.createNumber("0.0000000000000000000000000000000000000001"));
    }

    @Test
    public void testCreateNumber_LargeFloatFallback() {
        // Test fallback from Float to Double to BigDecimal
        // A number too large for Float but valid for Double
        String huge = "1e40"; 
        Number hugeNum = NumberUtils.createNumber(huge);
        assertTrue(hugeNum instanceof Double);
    }

    @Test
    public void testCreateNumber_InvalidFormat() {
        // Test default case in switch (invalid lastChar that isn't digit or .)
        try {
            NumberUtils.createNumber("123abc");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // expected
        }
    }
}
